#!/usr/bin/env python3
"""Bundle runner (Python stdlib only), generated by google-colab-runner.

Runs the bundle's jobs against a ComfyUI server: by default the one the notebook started on the
Google Colab runtime (http://127.0.0.1:8188). It detects the GPU, picks the highest packaged tier
that fits, uploads inputs, submits, polls, downloads outputs and records everything in
outputs/state.json, so a re-run after a dropped session skips finished jobs.

  python runner.py --list                 # show tiers, jobs and the GPU it would pick
  python runner.py [--url URL] [--tier auto|draft|standard|max] [--out outputs] [--max-minutes N]
"""
import argparse, json, os, shutil, subprocess, sys, time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import comfy_client as cc  # noqa: E402

ORDER = ["draft", "standard", "max"]


def detect_gpu():
    try:
        out = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader,nounits"],
                             capture_output=True, text=True, timeout=20).stdout.strip().splitlines()[0]
        name, mib = [x.strip() for x in out.split(",")]
        return name, round(float(mib) / 1024)
    except Exception:
        return None, None


def pick_tier(plan, gpus, name, vram, want):
    if want != "auto":
        return want
    for g in gpus["gpus"].values():
        if name and any(x in name.upper() for x in g["match"]):
            vram = vram or g["vram_gb"]
    fits = [t for t in ORDER if t in plan["tiers"] and plan["tiers"][t]["min_vram_gb"] <= (vram or 0)]
    return fits[-1] if fits else ORDER[0]


def last_frame(video, out_png):
    subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-sseof", "-0.05", "-i", video, "-frames:v", "1", out_png], check=True)
    return out_png


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--url", default=os.environ.get("COMFY_URL", "http://127.0.0.1:8188"))
    p.add_argument("--tier", default="auto", choices=["auto"] + ORDER)
    p.add_argument("--out", default=os.path.join(HERE, "outputs"))
    p.add_argument("--max-minutes", type=float, help="hard wall-clock cap for this runner (default: jobs.json max_session_minutes)")
    p.add_argument("--timeout", type=float, default=1800, help="per-job timeout in seconds")
    p.add_argument("--list", action="store_true")
    p.add_argument("--gpu-name"); p.add_argument("--vram-gb", type=float)
    a = p.parse_args()
    plan = json.load(open(os.path.join(HERE, "jobs.json")))
    name, vram = (a.gpu_name, a.vram_gb) if a.gpu_name else detect_gpu()
    tier = pick_tier(plan, plan["gpu_tiers"], name, vram, a.tier)
    jobs = plan["tiers"][tier]["jobs"]
    print(f"GPU: {name or 'none detected'} ({vram or '?'} GB) -> tier {tier} ({len(jobs)} jobs; manifest tier {plan['manifest_tier']})")
    if a.list:
        for j in jobs: print(f"  {j['id']:16} {j['kind']:6} {j['route']}")
        for n in plan["tiers"][tier]["notes"]: print("  note:", n)
        return 0
    os.makedirs(a.out, exist_ok=True)
    sp = os.path.join(a.out, "state.json")
    state = json.load(open(sp)) if os.path.isfile(sp) else {"tier": tier, "jobs": {}, "runs": []}
    if state["tier"] != tier:
        print(f"state.json was made at tier {state['tier']}; keeping that tier so the run stays consistent"); tier = state["tier"]; jobs = plan["tiers"][tier]["jobs"]
    state["runs"].append({"started": time.strftime("%Y-%m-%dT%H:%M:%S"), "gpu": name, "url": a.url})
    cap = a.max_minutes or plan.get("max_session_minutes"); t0 = time.time()

    def save():
        tmp = sp + ".tmp"; json.dump(state, open(tmp, "w"), indent=1); os.replace(tmp, sp)

    def local(ref):
        """Resolve job:/lastframe:/asset: references to a local file."""
        if ref.startswith("asset:"):
            return os.path.join(HERE, "assets", ref[6:])
        if ref.startswith("job:") or ref.startswith("lastframe:"):
            jid = ref.split(":", 1)[1]; prev = state["jobs"].get(jid) or {}
            if prev.get("status") != "done" or not prev.get("files"):
                raise LookupError(f"needs {jid}, which is not done")
            f = os.path.join(a.out, prev["files"][0])
            return last_frame(f, f + ".last.png") if ref.startswith("lastframe:") else f
        return os.path.join(HERE, ref)

    failed = 0
    for j in jobs:
        js = state["jobs"].setdefault(j["id"], {"status": "pending", "route": j["route"]})
        if js["status"] == "done":
            print(f"skip {j['id']} (done)"); continue
        if cap and (time.time() - t0) / 60 >= cap:
            print(f"cap_hit: {cap} min wall clock reached; stopping before {j['id']}"); state["cap_hit"] = True; break
        wf = json.load(open(os.path.join(HERE, j["workflow"])))
        try:
            for fi in j["files"]:  # uploads run every time, so a fresh session gets its inputs back
                name_ = cc.upload(a.url, local(fi["from"])).get("name")
                for t in fi["targets"]:
                    nid, _, inp = t.rpartition("."); wf[nid]["inputs"][inp] = name_
        except LookupError as e:
            js.update(status="blocked", error=str(e)); print(f"blocked {j['id']}: {e}"); save(); continue
        print(f"run  {j['id']} ({j['route']})", flush=True); t1 = time.time()
        try:
            pid = cc.submit(a.url, wf)
            r = cc.wait(a.url, [pid], a.timeout)[0]
            if r["status"] != "done":
                raise RuntimeError(f"status {r['status']}: {r.get('messages') or r.get('error')}")
            d = os.path.join(a.out, j["id"])
            files = [os.path.relpath(f, a.out) for f in cc.fetch(a.url, pid, d)]
            js.update(status="done", prompt_id=pid, files=files, seconds=round(time.time() - t1, 1),
                      seed=next((v for n in wf.values() for k, v in n.get("inputs", {}).items() if k in ("seed", "noise_seed") and isinstance(v, int)), None))
        except Exception as e:
            failed += 1; js.update(status="failed", error=str(e)[-500:]); print(f"FAIL {j['id']}: {e}")
            try:
                cc._req(a.url, "/system_stats", timeout=5)
            except Exception:
                save(); print("ComfyUI is unreachable (session dropped?). Re-run the runner cell after a restart; finished jobs are kept."); return 5
        save()
    save()
    done = sum(1 for v in state["jobs"].values() if v["status"] == "done")
    print(f"done {done}/{len(jobs)} jobs, {failed} failed. state: {sp}")
    return 0 if done == len(jobs) else 4


if __name__ == "__main__":
    sys.exit(main())
